cat > tests/mine525c.test.mjs <<'E'
// Этап 5.25b, раунд исправлений 3: сундуки и highestOre в кадре мира 1 (spec mine v5.2, правила 30–31; spec chests правила 14–16).
// ЛС(w1-mine-30min + сундуки) против O, порчи таблицы awardReq и юниты: min(урон, hp), награда в конце кадра, highestOre, выключенные правила.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRng } from '../core/rng.mjs';
import { makeWorld1 } from '../core/world1.mjs';
import { loadData } from '../oracle/mine525b/check525b.mjs';
import { runLsChests } from '../oracle/mine525c/lscheck525c.mjs';

const DATA = loadData();
const sig = (r) => JSON.stringify(r.chests);

test('ЛС(w1-mine-30min + сундуки): 180/180 по прежним ключам и по ключам сундуков', () => {
  const r = runLsChests(DATA);
  assert.equal(r.base.slices, 180);
  assert.equal(r.base.same, 180);
  assert.equal(r.chests.slices, 180);
  assert.equal(r.chests.same, 180, JSON.stringify(r.chests.bad));
});

const spoilAward = (f) => {
  const d = structuredClone(DATA);
  f(d.chests.tables.awardReq.rows);
  return d;
};
const PORCHI = {
  'awardReq item[0] + 1': (rows) => { rows[0][1] += 1; },
  'awardReq relic[1] − 1000': (rows) => { rows[1][2] -= 1000; },
};
for (const [name, f] of Object.entries(PORCHI)) {
  test(`порча: ${name} → ЛС по сундукам отличается от непорченой`, () => {
    const spoiled = runLsChests(spoilAward(f));
    assert.notEqual(sig(spoiled), sig(runLsChests(DATA)), name);
    assert.ok(spoiled.chests.same < 180, name);
  });
}

// ---- юниты

const REQ = DATA.chests.tables.awardReq.rows;
function mk(extra = {}, { lockstep = false, dmg = 1, hp = 10, ore = 2 } = {}) {
  const w1 = makeWorld1(DATA);
  const s = w1.init({ frame: 24, rocks: { n: 1, hp: [hp], x: [100], y: [200], ore: [ore], size: [1], zone: [0], golden: [false], rainbow: [false] },
    ore: Array(8).fill(0), bar: Array(26).fill(0), xp: 0, level: 1, task: 1, taskProgress: 0, screen: 1, floorsOpen: 1, clears: 0,
    stats: { pickaxeDamage: dmg, attackSpeed: 31, clickRadius: 50, expGainMulti: 1, floorClearRequirementMulti: 1 },
    rng: makeRng(0), ...(lockstep ? { lockstep: true } : {}), ...extra });
  return { w1, s };
}
const DOWN = { touch: { a: 0, x: 100, y: 280 }, actions: [] }; // один удар: 30 + 1 = attackSpeed
const IDLE = { touch: null, actions: [] };
const CH = { chestScale: 0, chests: 0, chestsEarned: 0, relicScale: 0, relicChests: 0, relicsEarned: 0 };

for (const lockstep of [false, true]) {
  const mode = lockstep ? 'лок-степ' : 'обычный';
  test(`шкалы: удар уроном 5 по камню с hp 3 даёт обеим шкалам +3 (${mode})`, () => {
    const { w1, s } = mk(CH, { lockstep, dmg: 5, hp: 3 });
    const t = w1.frame(s, DOWN);
    assert.equal(t.rocks.hp[0], 0);
    assert.equal(t.chestScale, 3);
    assert.equal(t.relicScale, 3);
  });

  test(`награда в конце кадра: шкала = порог − 1, удар 1 даёт сундук в этом же кадре, шкала 0 (${mode})`, () => {
    const { w1, s } = mk({ ...CH, chestScale: REQ[0][1] - 1, relicScale: REQ[0][2] - 1 }, { lockstep });
    const t = w1.frame(s, DOWN);
    assert.deepEqual([t.chests, t.chestsEarned, t.chestScale], [1, 1, 0]);
    assert.deepEqual([t.relicChests, t.relicsEarned, t.relicScale], [1, 1, 0]);
    // порог − 2: награды ещё нет
    const u = mk({ ...CH, chestScale: REQ[0][1] - 2 }, { lockstep });
    const v = u.w1.frame(u.s, DOWN);
    assert.deepEqual([v.chests, v.chestsEarned], [0, 0]);
  });
}

test('награда берёт порог по заработанному и не больше одной за кадр', () => {
  const { w1, s } = mk({ ...CH, chestsEarned: 3, chests: 2, chestScale: REQ[3][1] * 10 });
  const t = w1.frame(s, IDLE);
  assert.deepEqual([t.chests, t.chestsEarned, t.chestScale], [3, 4, 0]);
});

test('заработано за таблицей — ошибка; chestScale есть, а data.chests нет — ошибка', () => {
  const { w1, s } = mk({ ...CH, chestsEarned: REQ.length });
  assert.throws(() => w1.frame(s, IDLE), /за таблицей awardReq/);
  const w2 = makeWorld1({ ...DATA, chests: undefined });
  const s2 = w2.init({ ...mk(CH).s });
  assert.throws(() => w2.frame(s2, IDLE), /нет data\.chests\.tables\.awardReq/);
});

test('highestOre = max(highestOre, номер руды разрушенного камня)', () => {
  const a = mk({ ...CH, highestOre: 1 }, { hp: 1, ore: 3 });
  assert.equal(a.w1.frame(a.s, DOWN).highestOre, 3);
  const b = mk({ ...CH, highestOre: 5 }, { hp: 1, ore: 3 });
  assert.equal(b.w1.frame(b.s, DOWN).highestOre, 5);
  const c = mk({ ...CH, highestOre: 1 }, { hp: 10, ore: 3 }); // камень не разрушен
  assert.equal(c.w1.frame(c.s, DOWN).highestOre, 1);
});

test('состояние без chestScale: правила 30–31 выключены, поля не появляются', () => {
  const { w1, s } = mk({}, { hp: 1 });
  const t = w1.frame(w1.frame(s, DOWN), IDLE);
  for (const f of Object.keys(CH)) assert.ok(!(f in t), f);
  assert.ok(!('highestOre' in t));
  assert.equal(t.ore[2], 1); // камень разрушен
});
